package com.yihe.framework.ehr;

import java.util.*;
import java.time.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.yihe.framework.ehr.EhrAccess.*;
import static com.yihe.framework.ehr.EhrService.*;

/** Read-only, tenant-scoped operational analytics. No generated/demo statistics. */
@Service
public class CommunicationAnalytics {
    final EhrRepository db; final CommunicationService service;
    static final ZoneOffset CHINA=ZoneOffset.ofHours(8);
    static final List<String> REPLIES=Arrays.asList("doctor","manager","ai_assisted","auto_reply");
    public CommunicationAnalytics(EhrRepository db,CommunicationService service){this.db=db;this.service=service;}
    static LocalDateTime utc(Object v){return LocalDateTime.parse(str(v).replace(' ','T'));}
    static double round(double n){return Math.round(n*10)/10.0;}
    static Object percent(long n,long d){return d==0?null:round(100.0*n/d);}
    static class Filter {
        LocalDate start,end; String unit,category,origin,human; int page,size;
        Filter(Map<String,String> q){try{end=q.getOrDefault("end","").isEmpty()?LocalDate.now(CHINA):LocalDate.parse(q.get("end"));start=q.getOrDefault("start","").isEmpty()?end.minusDays(29):LocalDate.parse(q.get("start"));}catch(Exception e){throw new EhrException(422,"日期格式应为 yyyy-MM-dd");}
            require(!start.isAfter(end)&&!end.isAfter(LocalDate.now(CHINA))&&java.time.temporal.ChronoUnit.DAYS.between(start,end)<93,422,"请选择不晚于今天、最长93天的日期范围");
            unit=q.getOrDefault("unit","");category=q.getOrDefault("category","");origin=q.getOrDefault("origin","");human=q.getOrDefault("human","");
            require(unit.length()<=255,422,"单位名称过长");require(category.isEmpty()||CommunicationHistory.CATEGORIES.containsKey(category),422,"服务类型无效");require(Arrays.asList("","miniapp","admin","unknown").contains(origin),422,"会话来源无效");require(Arrays.asList("","yes","no").contains(human),422,"转人工条件无效");page=bounded(q.get("page"),1,1,100000);size=bounded(q.get("limit"),20,1,100);
        }
        String begin(){return start.atStartOfDay().minusHours(8).toString().replace('T',' ');}String finish(){return end.plusDays(1).atStartOfDay().minusHours(8).toString().replace('T',' ');}
        Filter previous(){Map<String,String> q=new HashMap<>();long days=java.time.temporal.ChronoUnit.DAYS.between(start,end)+1;q.put("start",start.minusDays(days).toString());q.put("end",start.minusDays(1).toString());q.put("unit",unit);q.put("category",category);q.put("origin",origin);q.put("human",human);return new Filter(q);}
    }
    static String originSql="CASE WHEN o.sender_role='employee' THEN 'miniapp' WHEN o.sender_role IN ('doctor','manager','ai_assisted','auto_reply') THEN 'admin' ELSE 'unknown' END";
    static class Data {List<Map<String,Object>> messages,events,threads=new ArrayList<>();Map<String,Map<String,Object>> byId=new LinkedHashMap<>();}
    Data read(EhrActor a,Filter f){
        List<Object> args=new ArrayList<>(Arrays.asList(a.scope,a.mode));String from=" FROM a_service_conversations c JOIN a_health_records r ON r.record_id=c.record_id AND r.scope_code=c.scope_code AND r.data_mode=c.data_mode JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode LEFT JOIN a_service_conversation_details d ON d.conversation_id=c.conversation_id LEFT JOIN a_service_messages o ON o.conversation_id=c.conversation_id AND o.seq=1 WHERE c.scope_code=? AND c.data_mode=? AND p.deleted_at IS NULL";
        if(!f.unit.isEmpty()){from+=" AND p.organization_name=?";args.add(f.unit);}if(!f.category.isEmpty()){from+=" AND COALESCE(d.category,'health')=?";args.add(f.category);}if(!f.origin.isEmpty()){from+=" AND "+originSql+"=?";args.add(f.origin);}
        if(!f.human.isEmpty()){from+=" AND "+(f.human.equals("no")?"NOT ":"")+"EXISTS(SELECT 1 FROM a_service_messages h WHERE h.conversation_id=c.conversation_id AND h.sender_role='system' AND h.body_text LIKE '%已接管会话%' AND h.created_at>=? AND h.created_at<?)";args.add(f.begin());args.add(f.finish());}
        List<Object> ma=new ArrayList<>();ma.add(f.begin());ma.add(f.finish());ma.addAll(args);
        String mf=from.replace(" FROM a_service_conversations c"," FROM a_service_messages m JOIN a_service_conversations c ON c.conversation_id=m.conversation_id").replace(" WHERE c.scope_code=?"," WHERE m.created_at>=? AND m.created_at<? AND c.scope_code=?");
        Data data=new Data();data.messages=db.all("SELECT m.conversation_id id,m.seq,m.sender_role role,m.body_text body,m.created_at time,c.service_status status,c.record_id recordId,c.created_at threadCreated,c.last_employee_seq lastEmployee,c.last_staff_seq lastStaff,p.employee_name name,p.employee_no code,p.organization_name unit,COALESCE(d.category,'health') category,d.satisfaction_score score,"+originSql+" origin"+mf+" ORDER BY m.created_at,m.conversation_id,m.seq LIMIT 200001",ma.toArray());
        require(data.messages.size()<=200000,413,"区间超过20万条消息，请缩小日期范围或按单位筛选");
        for(Map<String,Object> m:data.messages){String id=str(m.get("id"));Map<String,Object> t=data.byId.get(id);if(t==null){t=new LinkedHashMap<>(m);t.remove("body");t.remove("role");t.remove("seq");t.put("firstAt",m.get("time"));t.put("aiReplies",0L);t.put("humanReplies",0L);t.put("takeovers",0L);t.put("responseSeconds",null);t.put("responses",0L);t.put("responseSum",0L);t.put("firstResponse",null);data.byId.put(id,t);}String role=str(m.get("role"));if(REPLIES.contains(role)){String key=role.equals("auto_reply")?"aiReplies":"humanReplies";t.put(key,num(t.get(key))+1);}if(role.equals("system")&&str(m.get("body")).contains("已接管会话"))t.put("takeovers",num(t.get("takeovers"))+1);
            t.put("latestAt",m.get("time"));if(!role.equals("system")){String prev=str(t.get("previousRole"));if(REPLIES.contains(role)&&prev.equals("employee")){long sec=Math.max(0,Duration.between(utc(t.get("pendingAt")),utc(m.get("time"))).getSeconds());t.put("responseSum",num(t.get("responseSum"))+sec);t.put("responses",num(t.get("responses"))+1);if(t.get("firstResponse")==null)t.put("firstResponse",sec);m.put("responseSeconds",sec);}if(role.equals("employee")&&!prev.equals("employee"))t.put("pendingAt",m.get("time"));t.put("previousRole",role);t.put("active",true);}
        }
        data.byId.entrySet().removeIf(e->!Boolean.TRUE.equals(e.getValue().get("active")));for(Map<String,Object> t:data.byId.values()){t.remove("active");long samples=num(t.get("responses"));t.put("responseSeconds",samples==0?null:round(num(t.get("responseSum"))/(double)samples));t.put("pending",str(t.get("status")).equals("open")&&num(t.get("lastEmployee"))>num(t.get("lastStaff")));t.put("categoryName",CommunicationHistory.CATEGORIES.get(str(t.get("category"))));t.remove("previousRole");t.remove("pendingAt");data.threads.add(t);}
        // Events are read only for threads visible in the selected tenant/mode and filters.
        List<Object> ea=new ArrayList<>(Arrays.asList(f.begin(),f.finish()));ea.addAll(args);
        data.events=db.all("SELECT e.conversation_id id,e.outcome,e.created_at time,e.completed_at completedAt,e.detail"+from.replace(" FROM a_service_conversations c"," FROM a_service_reply_events e JOIN a_service_conversations c ON c.conversation_id=e.conversation_id").replace(" WHERE c.scope_code=?"," WHERE e.created_at>=? AND e.created_at<? AND c.scope_code=?")+" LIMIT 200001",ea.toArray());require(data.events.size()<=200000,413,"自动回复记录过多，请缩小筛选范围");data.events.removeIf(e->!data.byId.containsKey(str(e.get("id"))));return data;
    }
    Map<String,Object> totals(Data d){long ai=0,human=0,pending=0,takeovers=0,closed=0,rated=0,satisfied=0,samples=0,sum=0;for(Map<String,Object> t:d.threads){ai+=num(t.get("aiReplies"));human+=num(t.get("humanReplies"));takeovers+=num(t.get("takeovers"));if(Boolean.TRUE.equals(t.get("pending")))pending++;if(t.get("status").equals("closed"))closed++;if(t.get("score")!=null){rated++;if(num(t.get("score"))>=4)satisfied++;}samples+=num(t.get("responses"));sum+=num(t.get("responseSum"));}long handoffs=d.events.stream().filter(e->e.get("outcome").equals("handoff")).count();return map("conversations",d.threads.size(),"aiReplies",ai,"humanReplies",human,"pending",pending,"takeovers",takeovers,"handoffs",handoffs,"closed",closed,"rated",rated,"satisfied",satisfied,"satisfaction",percent(satisfied,rated),"responseSamples",samples,"averageSeconds",samples==0?null:round(sum/(double)samples));}
    @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
    public Map<String,Object> dashboard(EhrActor a,Map<String,String> q){service.staff(a);Filter f=new Filter(q);Data d=read(a,f),previous=read(a,f.previous());Map<String,Object> total=totals(d),prev=totals(previous);Map<String,Map<String,Object>> days=new LinkedHashMap<>(),weeks=new LinkedHashMap<>();for(LocalDate day=f.start;!day.isAfter(f.end);day=day.plusDays(1))days.put(day.toString(),map("date",day.toString(),"conversations",0L,"aiReplies",0L,"humanReplies",0L,"averageSeconds",null,"responseSamples",0L,"sum",0L));
        Map<String,List<Map<String,Object>>> perThread=new HashMap<>();for(Map<String,Object> m:d.messages)perThread.computeIfAbsent(str(m.get("id")),k->new ArrayList<>()).add(m);Map<String,Set<String>> active=new HashMap<>();long[] hours=new long[24],ratings=new long[5];Map<String,Set<String>> hourIds=new HashMap<>();Map<String,Long> topics=new LinkedHashMap<>();String[] terms={"体检报告","复查","血压","血糖","听力","肺功能","心理","随访","档案","健康方案","粉尘","饮食","运动"};for(String s:terms)topics.put(s,0L);
        for(Map<String,Object> m:d.messages){LocalDateTime time=utc(m.get("time")).plusHours(8);String day=time.toLocalDate().toString(),id=str(m.get("id")),role=str(m.get("role"));Map<String,Object> bucket=days.get(day);if(role.equals("system"))continue;active.computeIfAbsent(day,k->new HashSet<>()).add(id);hourIds.computeIfAbsent(String.valueOf(time.getHour()),k->new HashSet<>()).add(id);if(REPLIES.contains(role)){String key=role.equals("auto_reply")?"aiReplies":"humanReplies";bucket.put(key,num(bucket.get(key))+1);}if(m.get("responseSeconds")!=null){bucket.put("sum",num(bucket.get("sum"))+num(m.get("responseSeconds")));bucket.put("responseSamples",num(bucket.get("responseSamples"))+1);}if(role.equals("employee"))for(String term:terms)if(str(m.get("body")).contains(term))topics.put(term,topics.get(term)+1);}
        for(Map.Entry<String,Map<String,Object>> e:days.entrySet()){Map<String,Object> b=e.getValue();b.put("conversations",active.getOrDefault(e.getKey(),Collections.emptySet()).size());long samples=num(b.get("responseSamples"));b.put("averageSeconds",samples==0?null:round(num(b.get("sum"))/(double)samples));b.remove("sum");}
        for(int h=0;h<24;h++)hours[h]=hourIds.getOrDefault(String.valueOf(h),Collections.emptySet()).size();
        Map<String,Long> origins=new LinkedHashMap<>();origins.put("miniapp",0L);origins.put("admin",0L);origins.put("unknown",0L);Set<String> completedHandoffs=new HashSet<>(),handoffThreads=new HashSet<>();for(Map<String,Object> e:d.events)if(e.get("outcome").equals("handoff")&&d.byId.containsKey(str(e.get("id")))){String cid=str(e.get("id"));handoffThreads.add(cid);for(Map<String,Object> m:perThread.getOrDefault(cid,Collections.emptyList()))if(Arrays.asList("doctor","manager","ai_assisted").contains(str(m.get("role")))&&!utc(m.get("time")).isBefore(utc(e.get("time")))){completedHandoffs.add(cid);break;}}
        long quickClosed=0;for(Map<String,Object> t:d.threads){String source=str(t.get("origin"));origins.put(source,origins.get(source)+1);if(t.get("score")!=null)ratings[(int)num(t.get("score"))-1]++;long index=java.time.temporal.ChronoUnit.DAYS.between(f.start,utc(t.get("firstAt")).plusHours(8).toLocalDate())/7;String key=f.start.plusDays(index*7).toString();Map<String,Object> w=weeks.computeIfAbsent(key,k->map("date",k,"ai",0L,"human",0L,"pending",0L,"other",0L));String type=Boolean.TRUE.equals(t.get("pending"))?"pending":num(t.get("humanReplies"))>0?"human":num(t.get("aiReplies"))>0?"ai":"other";w.put(type,num(w.get(type))+1);if(t.get("status").equals("closed")){Optional<Map<String,Object>> close=perThread.getOrDefault(str(t.get("id")),Collections.emptyList()).stream().filter(m->m.get("role").equals("system")&&str(m.get("body")).contains("已结束本次服务")).reduce((x,y)->y);if(close.isPresent()&&!utc(close.get().get("time")).isBefore(utc(t.get("threadCreated")))&&Duration.between(utc(t.get("threadCreated")),utc(close.get().get("time"))).getSeconds()<=86400)quickClosed++;}}
        List<Map<String,Object>> topicRows=new ArrayList<>();topics.forEach((k,v)->{if(v>0)topicRows.add(map("name",k,"count",v));});topicRows.sort((x,y)->Long.compare(num(y.get("count")),num(x.get("count"))));if(topicRows.size()>10)topicRows.subList(10,topicRows.size()).clear();
        long replied=d.events.stream().filter(e->e.get("outcome").equals("replied")).count(),failed=d.events.stream().filter(e->e.get("outcome").equals("failed")).count();Map<String,Object> quality=map("resolved",percent(num(total.get("closed")),d.threads.size()),"within24h",percent(quickClosed,num(total.get("closed"))),"handoffCompleted",percent(completedHandoffs.size(),handoffThreads.size()),"handoffSamples",handoffThreads.size(),"aiAccuracy",null,"autoSuccess",percent(replied,replied+failed),"autoSamples",replied+failed);
        Map<String,Object> changes=new LinkedHashMap<>();for(String key:Arrays.asList("conversations","aiReplies","humanReplies","pending","takeovers","averageSeconds","satisfaction")){Object v=total.get(key),p=prev.get(key);changes.put(key,v==null||p==null||((Number)p).doubleValue()==0?null:round(100*(((Number)v).doubleValue()-((Number)p).doubleValue())/((Number)p).doubleValue()));}
        List<Map<String,Object>> issues=new ArrayList<>();if(num(total.get("pending"))>0)issues.add(map("type","pending","title","存在待回复职工会话","count",total.get("pending"),"description","区间内有消息且当前末条职工消息尚未获得服务回复。"));if(!handoffThreads.isEmpty())issues.add(map("type","handoff","title","转人工请求待跟进","count",handoffThreads.size()-completedHandoffs.size(),"description","以自动回复转人工事件之后的人工发送记录核验跟进情况。"));if(failed>0)issues.add(map("type","failed","title","自动回复失败需要排查","count",failed,"description","查看职工会话与自动回复执行记录，不自动重发。"));
        d.threads.sort((x,y)->str(y.get("latestAt")).compareTo(str(x.get("latestAt"))));int start=Math.min(d.threads.size(),(f.page-1)*f.size),end=Math.min(d.threads.size(),start+f.size);
        List<Map<String,Object>> units=db.all("SELECT DISTINCT p.organization_name name FROM a_employee_roster_profiles p WHERE p.scope_code=? AND p.data_mode=? AND p.deleted_at IS NULL AND p.organization_name<>'' ORDER BY p.organization_name LIMIT 501",a.scope,a.mode);
        return map("start",f.start.toString(),"end",f.end.toString(),"previousStart",f.previous().start.toString(),"previousEnd",f.previous().end.toString(),"summary",total,"previous",prev,"changes",changes,"days",days.values(),"weeks",weeks.values(),"origins",origins,"topics",topicRows,"hours",hours,"ratings",ratings,"quality",quality,"issues",issues,"items",d.threads.subList(start,end),"total",d.threads.size(),"page",f.page,"limit",f.size,"units",units,"categories",CommunicationHistory.CATEGORIES,"todayConversations",active.getOrDefault(LocalDate.now(CHINA).toString(),Collections.emptySet()).size(),"generatedAt",OffsetDateTime.now(CHINA).toString());
    }
    @Transactional(readOnly=true)
    public byte[] export(EhrActor a,Map<String,String> q){service.staff(a);Filter f=new Filter(q);Data d=read(a,f);require(d.threads.size()<=10000,413,"导出最多10000个会话，请缩小日期范围");StringBuilder out=new StringBuilder("\uFEFF职工姓名,工号,单位,会话编号,服务类型,区间首条时间UTC,区间末条时间UTC,自动回复数,人工回复数（含AI辅助）,首次响应秒,平均响应秒,人工接管次数,当前状态,满意度（1-5）\r\n");for(Map<String,Object> t:d.threads){for(String key:Arrays.asList("name","code","unit","id","categoryName","firstAt","latestAt","aiReplies","humanReplies","firstResponse","responseSeconds","takeovers","status","score"))out.append(CommunicationHistory.csv(t.get(key))).append(',');out.setLength(out.length()-1);out.append("\r\n");}return bytes(out.toString());}
}
